  '/jobs': { title: 'Jobs', snapshot: 'jobs', render: renderJobs },
  '/certificates': { title: 'Certificates', snapshot: 'certificates', render: renderCertificates },
  '/domains': { title: 'Domains', snapshot: 'domains', render: renderDomains },
