 */
export function pageHeader({ title, subtitle = '', actions = '' }) {
  const sub = subtitle ? `<p class="kit-muted">${esc(subtitle)}</p>` : '';
  const act = actions ? `<div class="kit-page-header__actions">${actions}</div>` : '';
